def data(self, *keys):
    try:
        # Check if any keys were provided and if so, filter the data accordingly
        if keys:
            data = {key: self[key] for key in keys}
        else:
            data = {key: self[key] for key in self.keys()}
        return data
    except IndexError:
        # If an out-of-bounds index was specified, raise an IndexError
        raise IndexError(f"Invalid index: {key}")
    except KeyError:
        # If a key was provided that doesn't exist in the record, set the value to None
        data[key] = None
        return data
    except:
        # If any other exception occurs, raise a generic exception
        raise Exception("An unexpected error occurred while trying to retrieve data from the record")

