def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        from neo4j.io import Bolt
        from neo4j.api import ROUTE, READ, WRITE
        from neo4j.exceptions import BoltProtocolError
        from neo4j.io.packstream import pack
        from neo4j.spatial import CARTESIAN_3D_TYPE, CARTESIAN_2D_TYPE
        from neo4j.time import DateTime, Duration, Instant, Time
        from neo4j.value import Typeless

        if not isinstance(mode, str) or mode not in (READ, WRITE):
            raise ValueError("Invalid mode: must be one of 'READ' or 'WRITE'")
        if not isinstance(bookmarks, (list, tuple)):
            raise ValueError("Invalid bookmarks: must be a list or tuple")
        if not isinstance(metadata, dict) or not all(isinstance(k, str) for k in metadata.keys()):
            raise ValueError("Invalid metadata: must be a dict with all str keys")
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise ValueError("Invalid timeout: must be a number")
        if db is not None and not isinstance(db, str):
            raise ValueError("Invalid database: must be a str")
        if imp_user is not None and not isinstance(imp_user, str):
            raise ValueError("Invalid impersonated user: must be a str")
        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise ValueError("Invalid dehydration_hooks: must be a dict")
        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise ValueError("Invalid hydration_hooks: must be a dict")

        def pack_value(value):
            if isinstance(value, Datetime):
                return CARTESIAN_3D_TYPE.pack(value.year, value.month, value.day, value.hour, value.minute, value.second, value.microsecond, 0)
            elif isinstance(value, Duration):
                return CARTESIAN_2D_TYPE.pack(value.months, value.days, value.seconds, value.nanoseconds, 0)
            elif isinstance(value, Instant):
                return CARTESIAN_3D_TYPE.pack(value.year, value.month, value.day, value.hour, value.minute, value.second, value.microsecond, 0)
            elif isinstance(value, Time):
                return CARTESIAN_2D_TYPE.pack(value.hours, value.minutes, value.seconds, value.microseconds, 0)
            else:
                return pack(value, dehydration_hooks)

        def unpack_value(value):
            if isinstance(value, typeless):
                return value
            elif isinstance(value, (Cartesian2Type, Cartesian3Type)):
                return value.unpack()
            else:
                return hydration_hooks.get(type(value), value)

        self._pack(Bolt.Run, [mode, bookmarks, metadata, timeout, db, imp_user], handlers)
        response = self._connection._connection.read()

        if response.parameters()["response_mode"] == ROUTE or response.parameters()["response_mode"] == WRITE:
            return response
        else:
            raise BoltProtocolError(f"Unknown response_mode {response.parameters()['response_mode']}")

