def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, dict):
        raise TypeError("fields must be a dictionary")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")
    if not all(isinstance(field, str) for field in fields):
        raise TypeError("all dictionary keys in fields must be strings")
    if not all(isinstance(value, (int, str)) for value in fields.values()):
        raise TypeError("all dictionary values in fields must be strings or integers")
    if not all(isinstance(key, str) for key in srid_map):
        raise TypeError("all dictionary keys in srid_map must be strings")
    if not all(isinstance(value, int) for value in srid_map.values()):
        raise TypeError("all dictionary values in srid_map must be integers")

    class Point(object):
        def __init__(self, **kwargs):
            for field in fields:
                setattr(self, field, kwargs.get(field, None))
            self.srid = srid_map.get(fields["srid"], 0)

        def __repr__(self):
            return "Point(x={}, y={}, srid={})".format(self.x, self.y, self.srid)
    return Point

