def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Step 1: Sort the classes in decreasing order of their inheritance depth
    sorted_classes = sorted(classes, key=lambda c: len(inspect.getmro(c)), reverse=True)

    # Step 2: Iterate over the sorted classes and remove any class that is a subclass of another class
    minimal_bases = []
    for i, cls in enumerate(sorted_classes):
        if not any(issubclass(other_cls, cls) for other_cls in sorted_classes[i + 1:]):
            minimal_bases.append(cls)

    # Step 3: Return the sorted minimal bases
    return sorted(minimal_bases, key=lambda c: c.__name__)

