def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Step 1: Extract manifest files from the provided manifest
    extracted_files = []
    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as f:
            manifest_data = json.load(f)
            for file in manifest_data['files']:
                extracted_files.append(file)

    # Step 2: Find all the digests needed by the files in the manifest
    needed_digests = set()
    for extracted_file in extracted_files:
        with open(extracted_file, 'rb') as f:
            content = f.read()
            needed_digests.update(Digest.from_bytes(content))

    # Step 3: Check if all the needed digests are present in the digests used
    for needed_digest in needed_digests:
        if not digests_used.has_digest(needed_digest):
            return False

    # Step 4: Check if all the digests in the digests used are needed
    for digest_used in digests_used:
        if not needed_digests.has_digest(digest_used):
            return False

    return True

