def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Ensure prior is an InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")

    # Check that prior is older than current
    if prior.version == self.version:
        raise ValueError("prior version must be older than current version")

    # Check that prior has same items as current
    if set(prior.items) != set(self.items):
        raise ValueError("prior must have same items as current inventory")

    # Check that prior has same item quantities as current
    for item in self.items:
        if prior.get_item_quantity(item) != self.get_item_quantity(item):
            raise ValueError("prior must have same item quantities as current inventory")

    # Check that prior has same costs for items as current
    for item in self.items:
        if prior.get_item_cost(item) != self.get_item_cost(item):
            raise ValueError("prior must have same item costs as current inventory")

    # Check that prior has same supplier for items as current
    for item in self.items:
        if prior.get_item_supplier(item) != self.get_item_supplier(item):
            raise ValueError("prior must have same item suppliers as current inventory")

    return True

