def get_logical_path_map(inventory: dict, version: str) -> dict:
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for logical_path in inventory["logical_paths"]:
        physical_path = inventory["physical_paths"][logical_path]
        if physical_path is not None:
            logical_path_map[logical_path] = set()
            for content_file in inventory["content_files"]:
                if content_file["logical_path"] == logical_path and content_file["version"] <= version:
                    logical_path_map[logical_path].add(content_file["physical_path"])
    return logical_path_map

