def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    invalid_files = []
    for file_path, fixity_block in fixity.items():
        if file_path not in manifest_files:
            invalid_files.append(file_path)
    if invalid_files:
        raise ValueError(f"The following files are not listed in the manifest: {invalid_files}")
    for file_path, fixity_block in fixity.items():
        if fixity_block["type"] not in ["md5", "sha1", "sha256"]:
            raise ValueError(f"The fixity block for {file_path} has an invalid type: {fixity_block['type']}")
    return True

