def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Validate all objects in the storage root
    if validate_objects:
        for obj in self.root.values():
            num_objects += 1
            if obj.is_valid():
                good_objects += 1
                if show_warnings and not obj.is_trusted():
                    print(f"WARNING: Object '{obj.name}' is not trusted!")
            else:
                print(f"ERROR: Object '{obj.name}' is not valid!")

    # Validate digests of all objects in the storage root
    if check_digests:
        for obj in self.root.values():
            if not obj.check_digest():
                print(f"ERROR: Object '{obj.name}' has an invalid digest!")
                num_objects += 1

    return num_objects, good_objects

