def validate_version_inventories(self, version_dirs: List[str]) -> None:
    """Validate that each version has an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    Args:
        version_dirs (List[str]): List of version directory names in sequence (1, 2, 3...).
    """
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    # Check that each version directory has an inventory up to that point
    current_version = 1
    for version_dir in version_dirs:
        inventory = self.read_inventory(version_dir)
        if not inventory:
            raise ValueError(f"Could not read inventory for version {current_version}")
        elif not inventory.is_valid():
            raise ValueError(f"Inventory for version {current_version} is invalid")
        current_version += 1

    # Check that the content digests in the inventories are consistent with the root inventory
    root_inventory = self.read_inventory(self.root_path)
    root_digests = {file["digest"] for file in root_inventory["files"]}
    for version_dir in version_dirs:
        inventory = self.read_inventory(version_dir)
        version_digests = {file["digest"] for file in inventory["files"]}
        if not version_digests.issuperset(root_digests):
            raise ValueError(f"Content digests in {version_dir} are not consistent with the root inventory")

