def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if bufsize is not None and not isinstance(bufsize, int):
        raise ValueError("bufsize must be an integer or None")

    if hasattr(seq, "read"):
        # File-like object
        if bufsize is not None:
            return (seq.read(bufsize), type(seq))
        else:
            return (seq, type(seq))
    elif isinstance(seq, (bytes, bytearray)):
        # Byte sequence
        return (seq, type(seq))
    elif isinstance(seq, str):
        # Text sequence
        if bufsize is not None:
            return (seq[:bufsize], type(seq))
        else:
            return (seq, type(seq))
    else:
        # Other sequence type
        return (seq, type(seq))

