def verifyClass(iface: type, candidate: type, tentative: bool = False) -> bool:
    """
    Verify that the *candidate* might correctly provide *iface*.

    Args:
        iface (type): The interface that the candidate might be providing.
        candidate (type): The class that might provide the interface.
        tentative (bool): Whether to perform a tentative check. Defaults to False.

    Returns:
        bool: Whether the candidate might correctly provide the interface.
    """
    if tentative:
        # Perform a tentative check
        if not isinstance(iface, type):
            raise TypeError(f"{iface} is not a valid interface")

        if not iface.isInterface():
            raise TypeError(f"{iface} is not an interface")

        if not iface.isAssignableFrom(candidate):
            raise TypeError(f"{candidate} is not assignable to {iface}")

        return True
    else:
        # Perform a strict check
        if not isinstance(iface, type):
            raise TypeError(f"{iface} is not a valid interface")

        if not isinstance(candidate, type):
            raise TypeError(f"{candidate} is not a valid class")

        if not iface.isInterface():
            raise TypeError(f"{iface} is not an interface")

        if not candidate.isSubclass(iface):
            raise TypeError(f"{candidate} is not a subclass of {iface}")

        return True

