def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Raises:
        ValueError: If the spec is not a valid JSON schema.
        KeyError: If the key is not found in the spec.
    """

    try:
        spec = json.loads(self.spec)
    except ValueError as e:
        raise ValueError("The spec is not a valid JSON schema") from e

    try:
        defaults = {key: spec[key] for key in spec if key not in self.arguments}
    except KeyError as e:
        raise KeyError("The key is not found in the spec") from e

    return defaults

