    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Check if the number of arguments is odd
    if len(args) % 2 == 1:
        raise ValueError("The number of arguments must be even.")

    # Check if the minimum and maximum values are correct
    for i in range(0, len(args), 2):
        if args[i] >= args[i + 1]:
            raise ValueError("Minimum value must be less than maximum value.")

    # Check if the values are within the range
    for i in range(1, len(args), 2):
        if not (args[i - 1] <= args[i] <= args[i + 1]):
            raise ValueError("Value must be within the range of minimum and maximum values.")

