def get_plugin_spec_flat_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    if not os.path.exists(plugin_dir):
        raise ValueError("The plugin directory does not exist")
    plugin_spec_file = os.path.join(plugin_dir, "plugin.spec")
    if not os.path.exists(plugin_spec_file):
        raise ValueError("The plugin spec file does not exist")
    with open(plugin_spec_file, "r") as f:
        plugin_spec = yaml.safe_load(f.read())
    if not isinstance(plugin_spec, dict):
        raise ValueError("The plugin spec is not a valid YAML dictionary")
    flat_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flat_dict[key + "." + subkey] = subvalue
        else:
            flat_dict[key] = value
    return flat_dict

